Shell Sort, also known as Shell's method, is an in-place comparison sort and an optimization of Insertion Sort. It improves upon the efficiency of Insertion Sort by allowing elements to be moved over larger distances in the initial stages, which significantly reduces the number of swaps required, especially for larger datasets. It was considered as the first algorithm to break the O(n²) time complexity barrier for sorting.It works by comparing elements that are far apart first, then gradually reducing the gap. This allows faster movement of elements across the array.Steps used in the algorithm are, Choose a gap sequence (commonly n/2, n/4, ... , 1).Sort elements at each gap using Insertion Sort.Reduce the gap and repeat until the gap becomes 1.Let's sort the list [22, 34, 25, 12, 64, 11, 90, 88, 45] using Shell Sort :
            C++

    #include <iostream>
#include <vector>
using namespace std;

void shellSort(vector<int>& arr) {
    int n = arr.size();

    // Start with a large gap, then reduce it step by step
    for (int gap = n / 2; gap > 0; gap /= 2) {

        // Perform a "gapped" insertion sort for this gap size
        for (int i = gap; i < n; i++) {

            // Current element to be placed correctly
            int temp = arr[i];  
            int j = i;

            // Shift elements that are greater than temp to make space
            while (j >= gap && arr[j - gap] > temp) {
                arr[j] = arr[j - gap];
                j -= gap;
            }

            // Place temp in its correct location
            arr[j] = temp;
        }
    }
}

// Utility function to print the vector
void printArray(const vector<int>& arr) {
    for (int num : arr)
        cout << num << " ";
    cout << endl;
}

int main() {
    vector<int> arr = {12, 34, 54, 2, 3}; 

    shellSort(arr);
    printArray(arr);

    return 0;
}


